/* The Fifth Floor: a 2389 office baked into a monster-truck arena. The room
   is scaled ten-to-one with its floor anchored at ground level. The double
   entry doors stand open at the north wall, and three ground-to-roof
   openings are cut where the racetrack punches through the east, south and
   west walls to loop the outside grounds. Geometry is baked as int16
   centimetre positions, uint16 indices and a flat material palette. */
const MTMOffice=(()=>{
  const S=.01,verts=decode16(""),tris=decode16(""),mats=decodeBytes("");
  const palette=[[0.86, 0.85, 0.8], [0.88, 0.88, 0.84], [0.25, 0.3, 0.29], [0.055, 0.065, 0.07], [0.014, 0.025, 0.03], [0.48, 0.29, 0.13], [0.24, 0.21, 0.23], [0.28, 0.31, 0.33], [0.51, 0.44, 0.33], [0.035, 0.07, 0.07], [0.13, 0.31, 0.08], [0.48, 0.035, 0.025], [0.18, 0.16, 0.12]];
  function base64(b){const raw=atob(b),out=new Uint8Array(raw.length);
    for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out;}
  function decode16(b){return new Int16Array(base64(b).buffer);}
  function decodeBytes(b){return base64(b);}
  // Collision slabs follow the surveyed shell. Openings: the double doors
  // (north, X -29.4..-11.1), the south re-entry (X 0..20), and two west
  // passages (Z 22..38 and Z -70..-46). Furniture stays soft scenery.
  function solids(){
    return [
      // north wall (door gap between the two runs)
      {x:-36.2,z:-96.7,hx:6.9,hz:.8},{x:13.4,z:-96.7,hx:24.5,hz:.8},
      // interior partitions
      {x:37.2,z:-76,hx:.75,hz:21.4},{x:54,z:-55.3,hx:17.6,hz:.75},
      {x:71,z:-30.8,hx:.75,hz:25.3},{x:96.6,z:-6.3,hx:26.4,hz:.76},
      // east wall
      {x:122.3,z:41.1,hx:.76,hz:48.1},
      // south wall (re-entry gap X 0..20)
      {x:-21.5,z:88.5,hx:21.6,hz:.76},{x:71.5,z:88.5,hx:51.5,hz:.76},
      // west wall, upper section (exit gap Z 22..38)
      {x:-42.3,z:8.2,hx:.76,hz:13.8},{x:-42.3,z:63.6,hx:.76,hz:25.6},
      // west wall, tall section (re-entry gap Z -70..-46)
      {x:-42.3,z:-83.7,hx:.76,hz:13.7},{x:-42.3,z:-25.8,hx:.76,hz:20.2}];
  }
  function build(T){
    const pos=new Float32Array(tris.length*3),col=new Float32Array(tris.length*3);
    for(let t=0;t<mats.length;t++){
      const [r,g,b]=palette[mats[t]];
      for(const vi of [tris[3*t],tris[3*t+1],tris[3*t+2]]){
        pos[3*vi]=verts[3*vi]*S;pos[3*vi+1]=verts[3*vi+1]*S;pos[3*vi+2]=verts[3*vi+2]*S;
        col[3*vi]=r;col[3*vi+1]=g;col[3*vi+2]=b;
      }
    }
    const geo=new T.BufferGeometry();
    geo.setAttribute('position',new T.Float32BufferAttribute(pos,3));
    geo.setAttribute('color',new T.Float32BufferAttribute(col,3));
    geo.setIndex(Array.from(tris));
    geo.computeVertexNormals();geo.computeBoundingSphere();
    const mesh=new T.Mesh(geo,new T.MeshLambertMaterial({vertexColors:true,side:T.DoubleSide}));
    mesh.receiveShadow=true;mesh.frustumCulled=false;
    return mesh;
  }
  return {build,solids};
})();
export {MTMOffice};
